1	#!/usr/bin/env node
2	/**
3	 * evolution-auto-runner.cjs — SessionStart hook
4	 * Auto-triggers Python evolution scripts when staleness thresholds exceeded.
5	 *
6	 * 4 checks:
7	 *   1. auto_evolve.py — knowledge hunting + integration (>7 days)
8	 *   2. scheduled-evolution-loop.py — prompt evolution proposals (>7 days)
9	 *   3. batch-auto-verify.py — expired prediction verification (>3 days)
10	 *   4. knowledge_hunter.py — external data hunting (>14 days)
11	 *
12	 * All processes spawned detached + unref'd. Fail-open (exit 0 always).
13	 */
14	
15	'use strict';
16	
17	const fs = require('fs');
18	const path = require('path');
19	const { spawn } = require('child_process');
20	
21	let isHookEnabled;
22	try {
23	  ({ isHookEnabled } = require('./lib/ck-config-utils.cjs'));
24	} catch {
25	  isHookEnabled = () => true;
26	}
27	
28	if (!isHookEnabled('evolution-auto-runner')) {
29	  process.exit(0);
30	}
31	
32	const DEBUG = !!process.env.CK_DEBUG;
33	const REPO_ROOT = path.resolve(__dirname, '..', '..');
34	const LOG_DIR = path.join(__dirname, '.logs');
35	const LOG_FILE = path.join(LOG_DIR, 'evolution-auto-runner.log');
36	const PYTHON_EXE = path.join(REPO_ROOT, '.claude', 'skills', '.venv', 'Scripts', 'python.exe');
37	
38	const LOCK_EXPIRY_MS = 600000; // 10 minutes
39	
40	const SCRIPTS = {
41	  autoEvolve: path.join(REPO_ROOT, '.claude', 'skills', 'business', 'deep-intelligence', 'auto_evolve.py'),
42	  scheduledEvolution: path.join(REPO_ROOT, '.claude', 'skills', 'business', 'compound', 'scheduled-evolution-loop.py'),
43	  batchVerify: path.join(REPO_ROOT, '.claude', 'skills', 'business', 'feedback_loop', 'batch-auto-verify.py'),
44	  knowledgeHunter: path.join(REPO_ROOT, '.claude', 'skills', 'business', 'deep-intelligence', 'knowledge_hunter.py'),
45	};
46	
47	const DATA_FILES = {
48	  evolutionLog: path.join(REPO_ROOT, 'data', 'deep-intelligence', 'evolution_log.json'),
49	  evolutionConfig: path.join(REPO_ROOT, '.claude', 'data', 'evolution-config.json'),
50	  pendingIndex: path.join(REPO_ROOT, 'data', 'predictions', 'pending-index.json'),
51	  batchVerifyMarker: path.join(LOG_DIR, 'batch-verify-last-run.txt'),
52	  knowledgeHuntMarker: path.join(LOG_DIR, 'knowledge-hunt-last-run.txt'),
53	};
54	
55	function ensureLogDir() {
56	  if (!fs.existsSync(LOG_DIR)) fs.mkdirSync(LOG_DIR, { recursive: true });
57	}
58	
59	function log(msg) {
60	  ensureLogDir();
61	  const line = `[${new Date().toISOString()}] ${msg}\n`;
62	  fs.appendFileSync(LOG_FILE, line);
63	  if (DEBUG) console.error(`[evolution-auto-runner] ${msg}`);
64	}
65	
66	function readJson(filepath) {
67	  try {
68	    return JSON.parse(fs.readFileSync(filepath, 'utf8'));
69	  } catch {
70	    return null;
71	  }
72	}
73	
74	function lockPath(name) {
75	  return path.join(LOG_DIR, `evolution-${name}.lock`);
76	}
77	
78	function isLocked(name) {
79	  const lp = lockPath(name);
80	  if (!fs.existsSync(lp)) return false;
81	  try {
82	    const data = JSON.parse(fs.readFileSync(lp, 'utf8'));
83	    return (Date.now() - new Date(data.started).getTime()) < LOCK_EXPIRY_MS;
84	  } catch {
85	    return false;
86	  }
87	}
88	
89	function acquireLock(name) {
90	  ensureLogDir();
91	  fs.writeFileSync(lockPath(name), JSON.stringify({
92	    started: new Date().toISOString(),
93	    pid: process.pid
94	  }));
95	}
96	
97	function releaseLock(name) {
98	  try { fs.unlinkSync(lockPath(name)); } catch {}
99	}
100	
101	function spawnDetached(name, scriptPath, args) {
102	  if (!fs.existsSync(PYTHON_EXE)) {
103	    log(`SKIP ${name}: python venv not found at ${PYTHON_EXE}`);
104	    return false;
105	  }
106	  if (!fs.existsSync(scriptPath)) {
107	    log(`SKIP ${name}: script not found at ${scriptPath}`);
108	    return false;
109	  }
110	  if (isLocked(name)) {
111	    log(`SKIP ${name}: already running (locked)`);
112	    return false;
113	  }
114	
115	  acquireLock(name);
116	
117	  try {
118	    const logOut = path.join(LOG_DIR, `${name}-stdout.log`);
119	    const logErr = path.join(LOG_DIR, `${name}-stderr.log`);
120	    const out = fs.openSync(logOut, 'a');
121	    const err = fs.openSync(logErr, 'a');
122	
123	    const child = spawn(PYTHON_EXE, [scriptPath, ...args], {
124	      cwd: REPO_ROOT,
125	      detached: true,
126	      stdio: ['ignore', out, err],
127	      windowsHide: true,
128	    });
129	
130	    child.on('close', () => releaseLock(name));
131	    child.unref();
132	
133	    log(`SPAWNED ${name} (pid=${child.pid})`);
134	    return true;
135	  } catch (e) {
136	    log(`ERROR ${name}: ${e.message}`);
137	    releaseLock(name);
138	    return false;
139	  }
140	}
141	
142	function daysSince(isoString) {
143	  if (!isoString) return Infinity;
144	  try {
145	    return (Date.now() - new Date(isoString).getTime()) / 86400000;
146	  } catch {
147	    return Infinity;
148	  }
149	}
150	
151	function daysSinceFile(filepath) {
152	  try {
153	    const content = fs.readFileSync(filepath, 'utf8').trim();
154	    return daysSince(content);
155	  } catch {
156	    return Infinity;
157	  }
158	}
159	
160	function writeMarker(filepath) {
161	  ensureLogDir();
162	  fs.writeFileSync(filepath, new Date().toISOString());
163	}
164	
165	// --- Check 1: Auto-evolve (knowledge hunting + integration) ---
166	function checkAutoEvolve() {
167	  const data = readJson(DATA_FILES.evolutionLog);
168	  if (!data) {
169	    log('CHECK auto-evolve: no evolution_log.json, triggering first run');
170	    return spawnDetached('auto-evolve', SCRIPTS.autoEvolve, []);
171	  }
172	
173	  const cycles = data.cycles || [];
174	  const lastCycle = cycles.length > 0 ? cycles[cycles.length - 1] : null;
175	  const lastTs = lastCycle ? lastCycle.timestamp : null;
176	  const days = daysSince(lastTs);
177	
178	  if (days > 7) {
179	    log(`CHECK auto-evolve: ${days.toFixed(1)} days since last cycle, triggering`);
180	    return spawnDetached('auto-evolve', SCRIPTS.autoEvolve, []);
181	  }
182	
183	  log(`CHECK auto-evolve: ${days.toFixed(1)} days ago, skipping (threshold=7)`);
184	  return false;
185	}
186	
187	// --- Check 2: Scheduled evolution loop ---
188	function checkScheduledEvolution() {
189	  const config = readJson(DATA_FILES.evolutionConfig);
190	  const lastRun = config ? config.last_run : null;
191	  const days = daysSince(lastRun);
192	
193	  if (days > 7) {
194	    log(`CHECK scheduled-evolution: ${days === Infinity ? 'never' : days.toFixed(1) + 'd'} since last run, triggering`);
195	    return spawnDetached('scheduled-evolution', SCRIPTS.scheduledEvolution, []);
196	  }
197	
198	  log(`CHECK scheduled-evolution: ${days.toFixed(1)} days ago, skipping (threshold=7)`);
199	  return false;
200	}
201	
202	// --- Check 3: Batch prediction verification ---
203	function checkBatchVerify() {
204	  const pending = readJson(DATA_FILES.pendingIndex);
205	  if (!pending || !Array.isArray(pending) || pending.length === 0) {
206	    log('CHECK batch-verify: no pending predictions, skipping');
207	    return false;
208	  }
209	
210	  const now = Date.now();
211	  const hasExpired = pending.some(p => {
212	    if (!p.deadline) return false;
213	    return new Date(p.deadline).getTime() < now;
214	  });
215	
216	  if (!hasExpired) {
217	    log('CHECK batch-verify: no expired predictions, skipping');
218	    return false;
219	  }
220	
221	  const days = daysSinceFile(DATA_FILES.batchVerifyMarker);
222	
223	  if (days > 3) {
224	    log(`CHECK batch-verify: expired predictions found, ${days === Infinity ? 'never' : days.toFixed(1) + 'd'} since last verify, triggering`);
225	    writeMarker(DATA_FILES.batchVerifyMarker);
226	    return spawnDetached('batch-verify', SCRIPTS.batchVerify, ['--all-expired']);
227	  }
228	
229	  log(`CHECK batch-verify: ${days.toFixed(1)} days ago, skipping (threshold=3)`);
230	  return false;
231	}
232	
233	// --- Check 4: Knowledge hunter (external data) ---
234	function checkKnowledgeHunt() {
235	  const days = daysSinceFile(DATA_FILES.knowledgeHuntMarker);
236	
237	  if (days > 14) {
238	    log(`CHECK knowledge-hunt: ${days === Infinity ? 'never' : days.toFixed(1) + 'd'} since last hunt, triggering`);
239	    writeMarker(DATA_FILES.knowledgeHuntMarker);
240	    return spawnDetached('knowledge-hunt', SCRIPTS.knowledgeHunter, []);
241	  }
242	
243	  log(`CHECK knowledge-hunt: ${days.toFixed(1)} days ago, skipping (threshold=14)`);
244	  return false;
245	}
246	
247	// --- Main ---
248	try {
249	  ensureLogDir();
250	  log('--- Evolution auto-runner starting ---');
251	
252	  let spawned = 0;
253	  if (checkAutoEvolve()) spawned++;
254	  if (checkScheduledEvolution()) spawned++;
255	  if (checkBatchVerify()) spawned++;
256	  if (checkKnowledgeHunt()) spawned++;
257	
258	  if (spawned > 0) {
259	    console.log(`🧬 Auto-evolution: ${spawned} background task(s) spawned`);
260	  }
261	
262	  log(`--- Done: ${spawned} task(s) spawned ---`);
263	} catch (e) {
264	  try { log(`CRASH: ${e.message}`); } catch {}
265	  if (DEBUG) console.error(`[evolution-auto-runner] ${e.message}`);
266	}
267	
268	process.exit(0);
