1	#!/usr/bin/env node
2	/**
3	 * SessionStart Hook - Learning Loop Trigger
4	 *
5	 * Fires: Once per session (startup, resume, clear, compact)
6	 * Purpose:
7	 *   1. Check for predictions with passed deadlines → inject reminder
8	 *   2. Check if weekly calibration review is due → inject reminder
9	 *   3. Scan both stores: predictions.json (legacy) + calibration-log.json (per-persona)
10	 *
11	 * Exit Codes:
12	 *   0 - Always (non-blocking advisory hook)
13	 */
14	
15	'use strict';
16	
17	const fs = require('fs');
18	const path = require('path');
19	
20	let isHookEnabled;
21	try {
22	  ({ isHookEnabled } = require('./lib/ck-config-utils.cjs'));
23	} catch {
24	  isHookEnabled = () => true;
25	}
26	
27	if (!isHookEnabled('learning-loop-trigger')) {
28	  process.exit(0);
29	}
30	
31	const ROOT = path.join(__dirname, '..', '..');
32	const PREDICTIONS_FILE = path.join(ROOT, 'data', 'assets', 'calibration', 'predictions.json');
33	const PERSONAS_DIR = path.join(__dirname, '..', 'skills', 'business', 'personas');
34	const REVIEW_STATE_FILE = path.join(ROOT, 'data', 'assets', 'calibration', 'last-weekly-review.json');
35	const BRIER_FILE = path.join(ROOT, 'data', 'calibration', 'brier-scores.jsonl');
36	const SKIP_DIRS = new Set(['shared', 'young-masters', '_template']);
37	const WEEKLY_INTERVAL_MS = 7 * 24 * 60 * 60 * 1000;
38	const EVOLUTION_CONFIG_PATH = path.join(__dirname, '..', 'data', 'evolution-config.json');
39	
40	// V2: Unified prediction store (Phase 4 Evolution Architecture)
41	const UNIFIED_PENDING_INDEX = path.join(ROOT, 'data', 'predictions', 'pending-index.json');
42	
43	function loadJson(filePath) {
44	  try {
45	    if (!fs.existsSync(filePath)) return null;
46	    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
47	  } catch {
48	    return null;
49	  }
50	}
51	
52	function isEvolutionDue() {
53	  const config = loadJson(EVOLUTION_CONFIG_PATH);
54	  if (!config) return true;
55	  const lastRun = config.last_evolution_run;
56	  if (!lastRun) return true;
57	  try {
58	    const age = Date.now() - new Date(lastRun).getTime();
59	    return age > WEEKLY_INTERVAL_MS;
60	  } catch {
61	    return true;
62	  }
63	}
64	
65	/**
66	 * Parse YYMMDD date string used in pulse_due_date field.
67	 * Returns a Date or null on error.
68	 */
69	function parsePulseDueDate(str) {
70	  if (!str || str.length !== 6) return null;
71	  try {
72	    const yy = parseInt(str.slice(0, 2), 10);
73	    const mm = parseInt(str.slice(2, 4), 10) - 1; // 0-indexed
74	    const dd = parseInt(str.slice(4, 6), 10);
75	    const year = 2000 + yy;
76	    return new Date(year, mm, dd);
77	  } catch {
78	    return null;
79	  }
80	}
81	
82	/**
83	 * Returns pending brier-score entries where observed == null AND pulse_due_date <= today.
84	 * Returns up to 5 most recent, sorted by ts_created desc.
85	 */
86	function getPendingBrierOutcomes() {
87	  if (!fs.existsSync(BRIER_FILE)) return [];
88	  const today = new Date();
89	  today.setHours(0, 0, 0, 0);
90	
91	  const pending = [];
92	  let raw;
93	  try {
94	    raw = fs.readFileSync(BRIER_FILE, 'utf8');
95	  } catch {
96	    return [];
97	  }
98	
99	  for (const line of raw.split('\n')) {
100	    const trimmed = line.trim();
101	    if (!trimmed) continue;
102	    let entry;
103	    try {
104	      entry = JSON.parse(trimmed);
105	    } catch {
106	      continue;
107	    }
108	    if (entry.observed !== null && entry.observed !== undefined) continue;
109	
110	    const due = parsePulseDueDate(entry.pulse_due_date);
111	    if (!due) continue;
112	    if (due > today) continue;  // not yet due
113	
114	    pending.push(entry);
115	  }
116	
117	  // Sort by ts_created descending, take 5 most recent
118	  pending.sort((a, b) => {
119	    const ta = a.ts_created || '';
120	    const tb = b.ts_created || '';
121	    return tb.localeCompare(ta);
122	  });
123	  return pending.slice(0, 5);
124	}
125	
126	function getExpiredLegacyPredictions() {
127	  const raw = loadJson(PREDICTIONS_FILE);
128	  if (!raw || !Array.isArray(raw.predictions)) return [];
129	
130	  const now = new Date();
131	  return raw.predictions.filter(p => {
132	    if (p.outcome != null) return false;
133	    const deadline = p.verification_date || p.outcome_date;
134	    if (!deadline) {
135	      // No explicit deadline — check if prediction is >30 days old
136	      try {
137	        const created = new Date(p.timestamp);
138	        return (now - created) > 30 * 24 * 60 * 60 * 1000;
139	      } catch { return false; }
140	    }
141	    try {
142	      return new Date(deadline) < now;
143	    } catch { return false; }
144	  });
145	}
146	
147	function getExpiredCalibrationPredictions() {
148	  const expired = [];
149	  if (!fs.existsSync(PERSONAS_DIR)) return expired;
150	
151	  const now = new Date();
152	  const entries = fs.readdirSync(PERSONAS_DIR, { withFileTypes: true });
153	
154	  for (const entry of entries) {
155	    if (!entry.isDirectory() || SKIP_DIRS.has(entry.name)) continue;
156	    const calPath = path.join(PERSONAS_DIR, entry.name, 'knowledge', 'calibration-log.json');
157	    const log = loadJson(calPath);
158	    if (!Array.isArray(log)) continue;
159	
160	    for (const pred of log) {
161	      if (pred.outcome != null) continue;
162	      if (pred.type === 'recommendation') continue;
163	
164	      const deadline = pred.verification_date;
165	      if (deadline) {
166	        try {
167	          if (new Date(deadline) < now) {
168	            expired.push({ ...pred, _persona: entry.name, _store: 'calibration' });
169	          }
170	        } catch { /* skip */ }
171	      } else {
172	        // No deadline — check if >30 days old
173	        try {
174	          const created = new Date(pred.timestamp);
175	          if ((now - created) > 30 * 24 * 60 * 60 * 1000) {
176	            expired.push({ ...pred, _persona: entry.name, _store: 'calibration' });
177	          }
178	        } catch { /* skip */ }
179	      }
180	    }
181	  }
182	  return expired;
183	}
184	
185	function isWeeklyReviewDue() {
186	  const state = loadJson(REVIEW_STATE_FILE);
187	  if (!state || !state.last_review) return true;
188	  try {
189	    const lastReview = new Date(state.last_review);
190	    return (Date.now() - lastReview.getTime()) > WEEKLY_INTERVAL_MS;
191	  } catch {
192	    return true;
193	  }
194	}
195	
196	/**
197	 * V2: Check unified prediction store for expired predictions (Evolution Architecture Phase 4)
198	 * Returns predictions from pending-index.json that are past their deadline
199	 */
200	function getExpiredUnifiedPredictions() {
201	  const index = loadJson(UNIFIED_PENDING_INDEX);
202	  if (!index || !Array.isArray(index.pending)) return [];
203	
204	  const today = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
205	
206	  return index.pending.filter(pred => {
207	    const deadline = pred.deadline;
208	    if (!deadline) return false;
209	    return deadline <= today;
210	  });
211	}
212	
213	function main() {
214	  try {
215	    const messages = [];
216	
217	    // 0. Check brier-scores.jsonl for pending stage0 outcomes (highest priority)
218	    const pendingBrier = getPendingBrierOutcomes();
219	    if (pendingBrier.length > 0) {
220	      const lines = [`⚠ PENDING OUTCOMES (${pendingBrier.length} prediction${pendingBrier.length > 1 ? 's' : ''} need results):`];
221	      pendingBrier.forEach((entry, idx) => {
222	        const label = entry.verdict || 'UNKNOWN';
223	        const p = entry.p_mountain != null ? entry.p_mountain : '?';
224	        const due = entry.pulse_due_date || '?';
225	        const summary = entry.case_id;
226	        lines.push(`${idx + 1}. ${summary}: verdict ${label} (p_mountain=${p}), due ${due}`);
227	        lines.push(`   → Run: /log-outcome --stage0-case-id ${summary} --observed 0`);
228	        lines.push(`      or: /log-outcome --stage0-case-id ${summary} --observed 1`);
229	      });
230	      lines.push(`\nRun /log-outcome for each to close the learning loop.`);
231	      messages.push(lines.join('\n'));
232	    }
233	
234	    // 0.5 V2: Check unified prediction store (Evolution Architecture)
235	    const unifiedExpired = getExpiredUnifiedPredictions();
236	    if (unifiedExpired.length > 0) {
237	      const lines = [`⚠ OUTCOME GATE: ${unifiedExpired.length} prediction(s) need outcomes before new advice:`];
238	      unifiedExpired.slice(0, 5).forEach((pred, idx) => {
239	        const domain = pred.domain || '?';
240	        const conf = pred.confidence != null ? (pred.confidence * 100).toFixed(0) + '%' : '?';
241	        const deadline = pred.deadline || '?';
242	        lines.push(`${idx + 1}. [${domain}] ${pred.id} — conf: ${conf}, deadline: ${deadline}`);
243	      });
244	      if (unifiedExpired.length > 5) {
245	        lines.push(`   ... and ${unifiedExpired.length - 5} more`);
246	      }
247	      lines.push(`\nRun: /log-outcome --id <pred_id> --observed <0|0.5|1>`);
248	      lines.push(`Or:  .claude\\skills\\.venv\\Scripts\\python.exe .claude/skills/business/feedback_loop/prediction-logger.py pending --expired`);
249	      messages.push(lines.join('\n'));
250	    }
251	
252	    // 1. Check expired predictions across both stores
253	    const legacyExpired = getExpiredLegacyPredictions();
254	    const calExpired = getExpiredCalibrationPredictions();
255	    const totalExpired = legacyExpired.length + calExpired.length;
256	
257	    if (totalExpired > 0) {
258	      const autoVerifiable = [];
259	      const manualOnly = [];
260	
261	      let autoKeywords = [];
262	      try {
263	        const kwPath = path.join(__dirname, '..', 'skills', 'business', 'feedback_loop', 'classification-keywords.json');
264	        const kw = JSON.parse(fs.readFileSync(kwPath, 'utf8'));
265	        autoKeywords = kw.auto_verifiable || [];
266	      } catch {
267	        autoKeywords = ['price', 'revenue', 'growth', 'funding', 'launch', 'release',
268	          'ship', 'order', 'paid', 'investment', 'stays under', 'arr', 'mrr'];
269	      }
270	
271	      for (const pred of [...legacyExpired, ...calExpired]) {
272	        const ctx = (pred.context || pred.prediction || '').toLowerCase();
273	        const isAuto = autoKeywords.some(kw => ctx.includes(kw));
274	        if (isAuto) {
275	          autoVerifiable.push(pred);
276	        } else {
277	          manualOnly.push(pred);
278	        }
279	      }
280	
281	      let msg = `⏰ Learning Loop: ${totalExpired} predictions have passed deadlines`;
282	      if (autoVerifiable.length > 0) {
283	        msg += ` (${autoVerifiable.length} auto-verifiable, ${manualOnly.length} manual)`;
284	        msg += `\nRun: \`.claude\\skills\\.venv\\Scripts\\python.exe .claude/skills/business/feedback_loop/batch-auto-verify.py --all-expired\``;
285	      }
286	      messages.push(msg);
287	    }
288	
289	    // 2. Check unmatched predictions awaiting outcomes
290	    const rawPreds = loadJson(PREDICTIONS_FILE);
291	    if (rawPreds && Array.isArray(rawPreds.predictions)) {
292	      const unmatchedCount = rawPreds.predictions.filter(p => p.outcome == null).length;
293	      if (unmatchedCount > 5) {
294	        messages.push(
295	          `📋 ${unmatchedCount} predictions awaiting outcomes.` +
296	          '\nRun: `.claude\\skills\\.venv\\Scripts\\python.exe .claude/skills/business/feedback_loop/prediction-linker.py --list-all-unmatched`'
297	        );
298	      }
299	    }
300	
301	    // 3. Check weekly review
302	    if (isWeeklyReviewDue()) {
303	      messages.push(
304	        '📊 Weekly calibration review is due.' +
305	        '\nRun: `.claude\\skills\\.venv\\Scripts\\python.exe .claude/skills/business/feedback_loop/weekly-prediction-review.py`'
306	      );
307	      messages.push(
308	        '🎯 Confidence caps may need refresh.' +
309	        '\nRun: `.claude\\skills\\.venv\\Scripts\\python.exe .claude/skills/business/feedback_loop/confidence-cap-generator.py`'
310	      );
311	      messages.push(
312	        '🧠 Weekly meta-learning digest available.' +
313	        '\nRun meta-learner agent or: `.claude\\skills\\.venv\\Scripts\\python.exe .claude/skills/business/compound/meta-learning-report.py`'
314	      );
315	    }
316	
317	    // Monthly prompt evolution check
318	    try {
319	      const proposalsPath = path.join(__dirname, '..', 'data', 'prompt-proposals.json');
